function configureStrip(options, viewportWidth) {
  if (!Number.isFinite(viewportWidth) || viewportWidth < 0) throw new TypeError('invalid viewport width');
  if (!options || typeof options !== 'object' || Array.isArray(options)) throw new TypeError('invalid options');
  if (!Number.isInteger(options.itemCount) || options.itemCount < 0 || options.itemCount > 10000) {
    throw new TypeError('invalid itemCount');
  }

  const validateLayout = (layout) => {
    if (!layout || typeof layout !== 'object' || Array.isArray(layout) ||
        !Number.isInteger(layout.visible) || layout.visible < 1 ||
        !Number.isFinite(layout.gap) || layout.gap < 0) {
      throw new TypeError('invalid layout');
    }
  };

  validateLayout(options.base);
  let chosen = options.base;
  let chosenAt = Infinity;
  const thresholds = options.thresholds === undefined ? {} : options.thresholds;
  if (!thresholds || typeof thresholds !== 'object' || Array.isArray(thresholds)) {
    throw new TypeError('invalid thresholds');
  }

  for (const key of Object.keys(thresholds)) {
    if (!/^(0|[1-9]\d*)$/.test(key) || !Number.isSafeInteger(Number(key))) {
      throw new TypeError('invalid threshold key');
    }
    validateLayout(thresholds[key]);
    const width = Number(key);
    if (width >= viewportWidth && width < chosenAt) {
      chosenAt = width;
      chosen = thresholds[key];
    }
  }

  let cycling = null;
  if (options.cycling !== undefined) {
    const value = options.cycling;
    if (!value || typeof value !== 'object' || Array.isArray(value) ||
        !Number.isFinite(value.interval) || value.interval <= 0 ||
        typeof value.pauseOnInput !== 'boolean') {
      throw new TypeError('invalid cycling');
    }
    cycling = { interval: value.interval, pauseOnInput: value.pauseOnInput };
  }

  const markers = Array.from({ length: options.itemCount }, (_, index) =>
    `#${String(index + 1).padStart(3, '0')}`
  );

  return { visible: chosen.visible, gap: chosen.gap, markers, cycling };
}

module.exports = { configureStrip };

