'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api), ['configureStrip']);
const { configureStrip } = api;

const options = {
  itemCount: 4,
  base: { visible: 1, gap: 2 },
  thresholds: {
    320: { visible: 2, gap: 3.5 },
    800: { visible: 4, gap: 8 }
  },
  cycling: { interval: 1500, pauseOnInput: true }
};
const small = configureStrip(options, 319.9);
assert.deepEqual(small, {
  visible: 1,
  gap: 2,
  markers: ['#001', '#002', '#003', '#004'],
  cycling: { interval: 1500, pauseOnInput: true }
});
assert.deepEqual(configureStrip(options, 320), {
  visible: 2,
  gap: 3.5,
  markers: ['#001', '#002', '#003', '#004'],
  cycling: { interval: 1500, pauseOnInput: true }
});
assert.equal(configureStrip(options, 999).visible, 4);
assert.notStrictEqual(small.cycling, options.cycling);
small.cycling.interval = 1;
small.markers[0] = 'changed';
assert.equal(options.cycling.interval, 1500);
assert.deepEqual(configureStrip(options, 0).markers, ['#001', '#002', '#003', '#004']);

assert.deepEqual(configureStrip({
  itemCount: 0,
  base: { visible: 1, gap: 0 },
  thresholds: {}
}, 0), { visible: 1, gap: 0, markers: [], cycling: null });

const many = configureStrip({ itemCount: 1001, base: { visible: 1, gap: 0 } }, 1);
assert.equal(many.markers[0], '#001');
assert.equal(many.markers[998], '#999');
assert.equal(many.markers[999], '#1000');
assert.equal(many.markers[1000], '#1001');

for (const width of [undefined, '10', NaN, Infinity, -1]) {
  assert.throws(() => configureStrip({ itemCount: 0, base: { visible: 1, gap: 0 } }, width), TypeError);
}

const invalidOptions = [
  null, [], {},
  { itemCount: -1, base: { visible: 1, gap: 0 } },
  { itemCount: 10001, base: { visible: 1, gap: 0 } },
  { itemCount: 1.5, base: { visible: 1, gap: 0 } },
  { itemCount: 1, base: null },
  { itemCount: 1, base: { visible: 0, gap: 0 } },
  { itemCount: 1, base: { visible: 1.2, gap: 0 } },
  { itemCount: 1, base: { visible: 1, gap: -1 } },
  { itemCount: 1, base: { visible: 1, gap: Infinity } },
  { itemCount: 1, base: { visible: 1, gap: 0 }, thresholds: [] },
  { itemCount: 1, base: { visible: 1, gap: 0 }, thresholds: { '01': { visible: 1, gap: 0 } } },
  { itemCount: 1, base: { visible: 1, gap: 0 }, thresholds: { '-0': { visible: 1, gap: 0 } } },
  { itemCount: 1, base: { visible: 1, gap: 0 }, thresholds: { '1.0': { visible: 1, gap: 0 } } },
  { itemCount: 1, base: { visible: 1, gap: 0 }, thresholds: { 2: { visible: 0, gap: 0 } } },
  { itemCount: 1, base: { visible: 1, gap: 0 }, cycling: null },
  { itemCount: 1, base: { visible: 1, gap: 0 }, cycling: { interval: 0, pauseOnInput: true } },
  { itemCount: 1, base: { visible: 1, gap: 0 }, cycling: { interval: 1, pauseOnInput: 1 } }
];
for (const value of invalidOptions) assert.throws(() => configureStrip(value, 100), TypeError);

